import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';
import { describe, expect, test } from 'vitest';

/**
 * Renders the logout modal's two count sentences from the compiled Paraglide messages in English for the counts 0, 1 and 2, so a message-format plugin that compiles their selectors differently fails here rather than in the modal.
 *
 * The compiled index is imported by its file path, because `vitest.config.ts` aliases `$lib/paraglide/messages` to a stub. It is generated by the frontend build or by `yarn workspace @openvaa/frontend paraglide:compile`.
 */

const COMPILE_COMMAND = 'yarn workspace @openvaa/frontend paraglide:compile';

const frontendRoot = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..', '..', '..');
const compiledIndexPath = path.join(frontendRoot, 'src', 'lib', 'paraglide', 'messages', '_index.js');

type CompiledMessage = (inputs: Record<string, unknown>, options: { locale: string }) => unknown;

const compiled: Record<string, unknown> | undefined = fs.existsSync(compiledIndexPath)
  ? await import(/* @vite-ignore */ compiledIndexPath)
  : undefined;

function render(key: string, inputs: Record<string, number>): unknown {
  if (!compiled) throw new Error(`${compiledIndexPath} is missing: run \`${COMPILE_COMMAND}\` first`);
  return (compiled[key] as CompiledMessage)(inputs, { locale: 'en' });
}

describe('contestantApp.logoutModal.questionsLeft in en', () => {
  test.each([
    [0, 'There are still 0 opinions to fill.'],
    [1, 'There is still one opinion to fill.'],
    [2, 'There are still 2 opinions to fill.']
  ])('opinionQuestionsLeft %i', (opinionQuestionsLeft, expected) => {
    expect(render('contestantApp.logoutModal.questionsLeft', { opinionQuestionsLeft })).toBe(expected);
  });
});

describe('contestantApp.logoutModal.itemsLeft in en', () => {
  test.each([
    [0, 0, 'There are still 0 items of basic info and 0 opinions to fill.'],
    [0, 1, 'There are still 0 items of basic info and one opinion to fill.'],
    [0, 2, 'There are still 0 items of basic info and 2 opinions to fill.'],
    [1, 0, 'There is still one item of basic info and 0 opinions to fill.'],
    [1, 1, 'There is still one item of basic info and one opinion to fill.'],
    [1, 2, 'There is still one item of basic info and 2 opinions to fill.'],
    [2, 0, 'There are still 2 items of basic info and 0 opinions to fill.'],
    [2, 1, 'There are still 2 items of basic info and one opinion to fill.'],
    [2, 2, 'There are still 2 items of basic info and 2 opinions to fill.']
  ])('infoQuestionsLeft %i, opinionQuestionsLeft %i', (infoQuestionsLeft, opinionQuestionsLeft, expected) => {
    expect(render('contestantApp.logoutModal.itemsLeft', { infoQuestionsLeft, opinionQuestionsLeft })).toBe(expected);
  });
});
